"""Run from the pinned checkout: python3 -B /path/to/retry_revert.py."""
import json
import sys
from pathlib import Path
sys.path.insert(0, str(Path.cwd() / 'tests'))
import gate_test as T
GT, git, Repo = T.GT, T.git, T.Repo


def world():
    r = Repo(git_init=False)
    (r.dot / 'merge.json').write_text(json.dumps(T.PRES))
    (r.root / 'AGENTS.md').write_text('original rules\n')
    git(r.root, 'init', '-q', '-b', 'master')
    r.commit('base')
    git(r.root, 'checkout', '-q', '-b', 'feature')
    (r.root / 'AGENTS.md').write_text('weakened rules\n')
    v = r.entity('alice', 'pr-head@1', {'state': 'open', 'repository': T.REPO, 'pr': 7, 'title': 'rules'})
    r.commit('rules change')
    git(r.root, 'checkout', '-q', 'master')
    until = 1793062800
    git(r.root, 'merge', '-q', '--no-ff', 'feature', '-m',
        f'Merge pull request #7\n\nwarrant-gate brake until {until}: #7 head version {v}')
    return r, GT.Base(r.root, git(r.root, 'rev-parse', 'HEAD')), until


class Hub:
    """Persist refs and PRs across gate runs, as the forge does. No network."""
    def __init__(self, until, fail_path):
        self.until, self.fail_path = until, fail_path
        self.refs, self.prs, self.calls, self.dispatched = {}, [], [], []

    def pull(self, n):
        return {'labels': ['hold']}

    def api(self, path, method='GET', body=None, pages=False):
        self.calls.append((path, method))
        if path == self.fail_path and method == 'POST':
            self.fail_path = None
            raise GT.Refused('transient server failure (HTTP 503)', 'GITHUB')
        if path.startswith('issues?'):
            return [[{'number': 7, 'labels': [{'name': 'hold'}]}]]
        if path.startswith('issues/7/events'):
            stamp = GT.time.strftime(GT.STAMP, GT.time.gmtime(self.until - 60))
            return [[{'event': 'labeled', 'label': {'name': 'hold'}, 'created_at': stamp}]]
        if path == 'git/trees' and method == 'POST':
            return {'sha': 'd' * 40}
        if path == 'git/commits' and method == 'POST':
            return {'sha': 'e' * 40}
        if path == 'git/refs' and method == 'POST':
            if body['ref'] in self.refs:
                raise GT.Refused('Reference already exists (HTTP 422)', 'GITHUB')
            self.refs[body['ref']] = body['sha']
            return {'ref': body['ref'], 'object': {'sha': body['sha']}}
        if path == 'tags?per_page=100':
            return [[]]
        if path == 'pulls' and method == 'POST':
            self.prs.append(body)
            return {'number': 8}
        raise AssertionError((path, method, body))

    def dispatch(self, workflow, branch):
        self.dispatched.append((workflow, branch))


def probe(fail_path):
    r, b, until = world()
    h = Hub(until, fail_path)
    first = GT.enforce_brakes(r.root, b, h, [], now=until - 1)
    second = GT.enforce_brakes(r.root, b, h, [], now=until + 1)
    third = GT.enforce_brakes(r.root, b, h, [], now=until + 60) if not h.prs else None
    print(json.dumps({'failed_at': fail_path, 'first': first, 'second': second, 'third': third,
                      'refs': h.refs, 'PRs': len(h.prs), 'dispatched': h.dispatched}, sort_keys=True))
    return h

control = probe('git/trees')
assert len(control.prs) == 1 and len(control.dispatched) == 1, 'control must recover before ref creation'
print('ok   C1 failure before creating a ref is retried successfully')
partial = probe('pulls')
if len(partial.prs) == 1 and len(partial.dispatched) == 1:
    print('ok   F1 partial revert creation recovers on the next gate run')
else:
    print('FAIL F1 a timely hold veto is never reverted after PR creation fails: the orphan ref makes every retry fail with HTTP 422')
    sys.exit(1)
